import java.time.*;
import java.time.temporal.TemporalAdjusters;

public class Main {
    public static void main(String[] args) {
        LocalDate tagih = LocalDate.of(2026, 10, 30);
        LocalDate jatuhTempo = tagih.plusDays(7);
        LocalDate awalBulan = tagih.withDayOfMonth(1);
        LocalDate seninDepan = tagih.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
        System.out.println(jatuhTempo);
        System.out.println(awalBulan);
        System.out.println(seninDepan);
        System.out.println(tagih);
    }
}

