        LocalDate pesan = LocalDate.of(2026, 1, 15);
        LocalDate bayar = pesan.plusDays(10);
        LocalDate cekUlang = bayar.plusMonths(1);
        LocalDate akhirBulan = pesan.with(TemporalAdjusters.lastDayOfMonth());
        System.out.println(bayar);
        System.out.println(cekUlang);
        System.out.println(akhirBulan);
    }
}

